maximal_square(Matrix) -> Side = rows(Matrix, lists:duplicate(length(hd(Matrix)), 0), 0), Side * Side. rows([], _, Best) -> Best; rows([Row | Rest], Previous, Best) -> {Current, NextBest} = columns(Row, Previous, 0, 0, [], Best), rows(Rest, Current, NextBest). columns([], [], _, _, Reversed, Best) -> {lists:reverse(Reversed), Best}; columns([Cell | Cells], [Above | Tail], Left, Diagonal, Reversed, Best) -> Value = case Cell of $1 -> 1 + min(Left, min(Above, Diagonal)); _ -> 0 end, columns(Cells, Tail, Value, Above, [Value | Reversed], max(Best, Value)).
